<?php use Passport\Copy; ?>
<p class="eyebrow"><?= $e($t('STEWARDSHIP · PRIVATE')) ?></p><h1><?= $e($story['title']) ?></h1><p><?= $e($t('Record only choices actually declared by the contributor. Changes retain a dated history. Past approvals keep their original consent snapshot.')) ?></p><div class="actions"><a href="/p/<?= $e($story['id']) ?>"><?= $e($t('passport')) ?> ↗</a><a href="/dashboard/requests"><?= $e($t('requests')) ?> ↗</a><a href="/ledger?storyId=<?= $e($story['id']) ?>"><?= $e($t('ledger')) ?> ↗</a></div>
<section class="card"><h2><?= $e($t('Consent, person by person')) ?></h2><form data-consent="<?= $e($story['id']) ?>"><?php foreach ($story['contributors'] as $person): ?><fieldset><legend><?= $e($person['name']) ?> · <?= $e($person['role']) ?></legend><div class="consent-tags"><?php foreach (Copy::PURPOSES as $purpose => $label): ?><label class="check"><input type="checkbox" data-person="<?= $e($person['id']) ?>" data-purpose="<?= $e($purpose) ?>" <?= ($person['consents'][$purpose]['granted'] ?? false) ? 'checked' : '' ?>> <?= $e($label) ?></label><?php endforeach ?></div></fieldset><?php endforeach ?><button class="button"><?= $e($t('Save declared consent')) ?></button><p class="form-message" role="status" aria-live="polite"></p></form></section>
<section class="card"><h2><?= $e($t('Declared review status')) ?></h2><p><?= $e($t('These badges record a manual declaration. They do not verify identity, authority or ownership.')) ?></p><form data-api="/api/stories/<?= $e($story['id']) ?>/status" data-method="PATCH"><label><?= $e($t('Status')) ?><select name="status"><?php foreach (Copy::STATUS as $value => $label): ?><option value="<?= $e($value) ?>" <?= $story['status'] === $value ? 'selected' : '' ?>><?= $e($label) ?></option><?php endforeach ?></select></label><button class="button secondary"><?= $e($t('Save status')) ?></button><p class="form-message" role="status" aria-live="polite"></p></form></section>
